CREATE TABLE public.class_quiz_keys (content_id uuid PRIMARY KEY REFERENCES public.class_content(id) ON DELETE CASCADE, answers jsonb NOT NULL);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.class_quiz_keys TO authenticated;
GRANT ALL ON public.class_quiz_keys TO service_role;
ALTER TABLE public.class_quiz_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY quiz_keys_teacher ON public.class_quiz_keys TO authenticated USING (EXISTS (SELECT 1 FROM public.class_content c WHERE c.id = content_id AND public.is_class_teacher(c.class_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.class_content c WHERE c.id = content_id AND public.is_class_teacher(c.class_id)));
INSERT INTO public.class_quiz_keys(content_id,answers) SELECT id, (SELECT jsonb_agg(q->'answer' ORDER BY ord) FROM jsonb_array_elements(questions) WITH ORDINALITY a(q,ord)) FROM public.class_content WHERE kind='quiz' AND jsonb_array_length(questions)>0;
UPDATE public.class_content SET questions=(SELECT jsonb_agg(q - 'answer' ORDER BY ord) FROM jsonb_array_elements(questions) WITH ORDINALITY a(q,ord)) WHERE kind='quiz' AND questions IS NOT NULL;
CREATE FUNCTION public.extract_class_quiz_keys() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb; keys jsonb; BEGIN IF NEW.kind='quiz' THEN IF NEW.questions IS NULL OR jsonb_array_length(NEW.questions) NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'A quiz needs 1 to 50 questions'; END IF; FOR q IN SELECT value FROM jsonb_array_elements(NEW.questions) LOOP IF jsonb_typeof(q->'answer') IS DISTINCT FROM 'number' OR (q->>'answer')::integer < 0 OR (q->>'answer')::integer >= jsonb_array_length(q->'options') THEN RAISE EXCEPTION 'Invalid quiz answer'; END IF; END LOOP; SELECT jsonb_agg(q->'answer' ORDER BY ord) INTO keys FROM jsonb_array_elements(NEW.questions) WITH ORDINALITY a(q,ord); INSERT INTO public.class_quiz_keys VALUES(NEW.id,keys); UPDATE public.class_content SET questions=(SELECT jsonb_agg(q - 'answer' ORDER BY ord) FROM jsonb_array_elements(NEW.questions) WITH ORDINALITY a(q,ord)) WHERE id=NEW.id; END IF; RETURN NEW; END $$;
CREATE TRIGGER extract_class_quiz_keys AFTER INSERT ON public.class_content FOR EACH ROW EXECUTE FUNCTION public.extract_class_quiz_keys();
CREATE TABLE public.class_quiz_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), content_id uuid NOT NULL REFERENCES public.class_content(id) ON DELETE CASCADE, student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, answers jsonb NOT NULL, score integer NOT NULL, total_questions integer NOT NULL, submitted_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.class_quiz_attempts TO authenticated;
GRANT ALL ON public.class_quiz_attempts TO service_role;
ALTER TABLE public.class_quiz_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY quiz_attempt_read ON public.class_quiz_attempts FOR SELECT TO authenticated USING (student_id=auth.uid() OR EXISTS(SELECT 1 FROM public.class_content c WHERE c.id=content_id AND public.is_class_teacher(c.class_id)));
CREATE FUNCTION public.submit_class_quiz(p_content uuid,p_answers jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.class_content; keys jsonb; n integer; earned integer:=0; i integer; result_id uuid; BEGIN SELECT * INTO c FROM public.class_content WHERE id=p_content AND kind='quiz'; IF auth.uid() IS NULL OR c.id IS NULL OR NOT public.is_class_member(c.class_id) THEN RAISE EXCEPTION 'Join this class to take its quiz'; END IF; SELECT answers INTO keys FROM public.class_quiz_keys WHERE content_id=p_content; n:=jsonb_array_length(c.questions); IF keys IS NULL OR jsonb_typeof(p_answers) IS DISTINCT FROM 'array' OR jsonb_array_length(p_answers)<>n THEN RAISE EXCEPTION 'Answer every question'; END IF; FOR i IN 0..n-1 LOOP IF jsonb_typeof(p_answers->i) IS DISTINCT FROM 'number' OR (p_answers->>i)::numeric <> trunc((p_answers->>i)::numeric) OR (p_answers->>i)::integer NOT BETWEEN 0 AND jsonb_array_length(c.questions->i->'options')-1 THEN RAISE EXCEPTION 'Invalid answer'; END IF; IF p_answers->i=keys->i THEN earned:=earned+1; END IF; END LOOP; INSERT INTO public.class_quiz_attempts(content_id,student_id,answers,score,total_questions) VALUES(p_content,auth.uid(),p_answers,earned,n) RETURNING id INTO result_id; RETURN jsonb_build_object('id',result_id,'score',earned,'total_questions',n); END $$;
REVOKE ALL ON FUNCTION public.submit_class_quiz(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_class_quiz(uuid,jsonb) TO authenticated;
CREATE TABLE public.class_lesson_completions (content_id uuid NOT NULL REFERENCES public.class_content(id) ON DELETE CASCADE,student_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(content_id,student_id));
GRANT SELECT,INSERT ON public.class_lesson_completions TO authenticated;
GRANT ALL ON public.class_lesson_completions TO service_role;
ALTER TABLE public.class_lesson_completions ENABLE ROW LEVEL SECURITY;
CREATE POLICY class_lesson_read ON public.class_lesson_completions FOR SELECT TO authenticated USING(student_id=auth.uid() OR EXISTS(SELECT 1 FROM public.class_content c WHERE c.id=content_id AND public.is_class_teacher(c.class_id)));
CREATE POLICY class_lesson_complete ON public.class_lesson_completions FOR INSERT TO authenticated WITH CHECK(student_id=auth.uid() AND EXISTS(SELECT 1 FROM public.class_content c WHERE c.id=content_id AND c.kind='lesson' AND public.is_class_member(c.class_id)));
CREATE TABLE public.class_message_reads(message_id uuid NOT NULL REFERENCES public.class_messages(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(message_id,user_id));
GRANT SELECT,INSERT ON public.class_message_reads TO authenticated;
GRANT ALL ON public.class_message_reads TO service_role;
ALTER TABLE public.class_message_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_message_reads ON public.class_message_reads FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY add_message_read ON public.class_message_reads FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.class_messages m WHERE m.id=message_id AND (m.recipient_id=auth.uid() OR (m.recipient_id IS NULL AND public.is_class_member(m.class_id)))));
CREATE FUNCTION public.protect_class_message() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.class_id IS DISTINCT FROM OLD.class_id OR NEW.sender_id IS DISTINCT FROM OLD.sender_id OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id OR NEW.body IS DISTINCT FROM OLD.body OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Only read status may change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_class_message BEFORE UPDATE ON public.class_messages FOR EACH ROW EXECUTE FUNCTION public.protect_class_message();